// Extract telemetry values
const data = msg.payload.telemetry || msg.payload;
const temp = parseFloat(data.temperature || 0);
const vib = parseFloat(data.vibration || 0);
const press = parseFloat(data.pressure || 0);
const health = parseFloat(msg.payload.health_index || 100);

let actuatorMsg = null;
let alertMsg = null;

// Decision Rule 1: Thermal Runaway Protection
if (temp > 85.0) {
    actuatorMsg = {
        topic: 'iot/actuators/cooling',
        payload: {
            command: 'ENGAGE_MAX_COOLING_CYCLE',
            device: data.device_id || 'UNKNOWN',
            target_speed_pct: 100,
            timestamp: new Date().toISOString()
        }
    };
    alertMsg = {
        topic: 'iot/alerts/critical',
        payload: {
            severity: 'CRITICAL',
            title: 'THERMAL RUNAWAY DETECTED',
            temperature: temp,
            action: 'Cooling at 100% engaged autonomously'
        }
    };
}
// Decision Rule 2: Overpressure Relief
else if (press > 8.0) {
    actuatorMsg = {
        topic: 'iot/actuators/valves',
        payload: {
            command: 'OPEN_PRESSURE_RELEASE_VALVE_50%',
            device: data.device_id || 'UNKNOWN',
            timestamp: new Date().toISOString()
        }
    };
    alertMsg = {
        topic: 'iot/alerts/critical',
        payload: {
            severity: 'CRITICAL',
            title: 'HYDRAULIC OVERPRESSURE',
            pressure: press,
            action: 'Relief valve opened'
        }
    };
}
// Decision Rule 3: High Bearing Vibration
else if (vib > 7.0) {
    actuatorMsg = {
        topic: 'iot/actuators/motors',
        payload: {
            command: 'DERATE_RPM_TO_40%',
            device: data.device_id || 'UNKNOWN',
            timestamp: new Date().toISOString()
        }
    };
    alertMsg = {
        topic: 'iot/alerts/warning',
        payload: {
            severity: 'WARNING',
            title: 'BEARING VIBRATION ANOMALY',
            vibration: vib,
            action: 'Motor RPM derated'
        }
    };
}

// Return array of outputs: [Actuator output, Alert output]
return [actuatorMsg, alertMsg];
